<?php

declare(strict_types=1);

namespace EventMenu\Services;

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use PDO;
use RuntimeException;

final class InventoryCountService
{
    public function create(string $notes=''): int
    {
        Auth::requirePermission('inventory.manage');$tenantId=Auth::tenantId();$userId=Auth::id();if(!$tenantId||!$userId)throw new RuntimeException('Sessão inválida.');$unit=(new OperatingUnitService())->requireCurrent();$unitId=(int)$unit['id'];$notes=mb_substr(trim($notes),0,1000);
        return Database::transaction(function(PDO$pdo)use($tenantId,$userId,$unitId,$notes):int{$open=$pdo->prepare(Database::portableSql($pdo,'SELECT id FROM inventory_counts WHERE tenant_id=? AND unit_id=? AND status="open" ORDER BY id DESC LIMIT 1 FOR UPDATE'));$open->execute([$tenantId,$unitId]);if($existing=(int)$open->fetchColumn())return$existing;$s=$pdo->prepare('INSERT INTO inventory_counts (tenant_id,unit_id,status,notes,created_by) VALUES (?, ?,"open",?,?)');$s->execute([$tenantId,$unitId,$notes?:null,$userId]);$id=(int)$pdo->lastInsertId();$products=$pdo->prepare('SELECT p.id,COALESCE(ui.stock_qty,0) available_qty,COALESCE((SELECT SUM(sr.quantity) FROM stock_reservations sr WHERE sr.tenant_id=p.tenant_id AND sr.unit_id=? AND sr.product_id=p.id AND sr.status="reserved"),0) reserved_qty FROM products p LEFT JOIN unit_inventory ui ON ui.tenant_id=p.tenant_id AND ui.unit_id=? AND ui.product_id=p.id WHERE p.tenant_id=? AND p.track_stock=1 AND p.active=1 ORDER BY p.id');$products->execute([$unitId,$unitId,$tenantId]);$ins=$pdo->prepare('INSERT INTO inventory_count_items (inventory_count_id,product_id,expected_qty,counted_qty,difference_qty) VALUES (?,?,?,NULL,NULL)');foreach($products->fetchAll()as$row)$ins->execute([$id,$row['id'],round((float)$row['available_qty']+(float)$row['reserved_qty'],6)]);Auth::audit('inventory.count_created','inventory_count',(string)$id,['unit_id'=>$unitId]);return$id;});
    }

    public function save(int$countId,array$counts): void
    {
        Auth::requirePermission('inventory.manage');$tenantId=Auth::tenantId();if(!$tenantId)throw new RuntimeException('Empresa inválida.');$current=(new OperatingUnitService())->requireCurrent();$unitId=(int)$current['id'];Database::transaction(function(PDO$pdo)use($tenantId,$unitId,$countId,$counts):void{$count=$this->lockedCount($pdo,$tenantId,$countId);if((int)$count['unit_id']!==$unitId)throw new RuntimeException('Esta contagem pertence a outra unidade.');if($count['status']!=='open')throw new RuntimeException('Esta contagem já foi encerrada.');$valid=$pdo->prepare('SELECT id,expected_qty FROM inventory_count_items WHERE inventory_count_id=?');$valid->execute([$countId]);$map=[];foreach($valid->fetchAll()as$row)$map[(int)$row['id']]=$row;$u=$pdo->prepare('UPDATE inventory_count_items SET counted_qty=?,difference_qty=? WHERE id=? AND inventory_count_id=?');foreach($counts as$itemId=>$raw){$itemId=(int)$itemId;if(!isset($map[$itemId]))continue;$text=trim((string)$raw);if($text==='')continue;$qty=(float)str_replace(',','.',$text);if(!is_finite($qty)||$qty<0)throw new RuntimeException('Há uma quantidade contada inválida.');$qty=round($qty,6);$difference=round($qty-(float)$map[$itemId]['expected_qty'],6);$u->execute([$qty,$difference,$itemId,$countId]);}});Auth::audit('inventory.count_saved','inventory_count',(string)$countId);
    }

    public function approve(int$countId): void
    {
        Auth::requirePermission('inventory.approve');$tenantId=Auth::tenantId();$userId=Auth::id();if(!$tenantId||!$userId)throw new RuntimeException('Sessão inválida.');$current=(new OperatingUnitService())->requireCurrent();$unitId=(int)$current['id'];Database::transaction(function(PDO$pdo)use($tenantId,$userId,$unitId,$countId):void{$count=$this->lockedCount($pdo,$tenantId,$countId);if((int)$count['unit_id']!==$unitId)throw new RuntimeException('Esta contagem pertence a outra unidade.');if($count['status']==='approved')return;if($count['status']!=='open')throw new RuntimeException('Esta contagem não pode ser aprovada.');$s=$pdo->prepare('SELECT ici.*,p.name,p.average_cost_cents,p.min_stock_qty FROM inventory_count_items ici JOIN products p ON p.id=ici.product_id WHERE ici.inventory_count_id=? ORDER BY ici.id');$s->execute([$countId]);$items=$s->fetchAll();if(!$items)throw new RuntimeException('Contagem sem produtos.');foreach($items as$item)if($item['counted_qty']===null)throw new RuntimeException('Conte todos os produtos antes de aprovar.');foreach($items as$item){$productId=(int)$item['product_id'];$reserved=$pdo->prepare('SELECT COALESCE(SUM(quantity),0) FROM stock_reservations WHERE tenant_id=? AND unit_id=? AND product_id=? AND status="reserved"');$reserved->execute([$tenantId,$unitId,$productId]);$reservedQty=(float)$reserved->fetchColumn();$counted=(float)$item['counted_qty'];if($counted+.0005<$reservedQty)throw new RuntimeException('A contagem de '.$item['name'].' ('.$this->formatQty($counted).') é menor que o total já reservado em pedidos ('.$this->formatQty($reservedQty).'). Resolva as reservas antes de aprovar.');$insert=Database::portableSql($pdo,'INSERT IGNORE INTO unit_inventory (tenant_id,unit_id,product_id,stock_qty,average_cost_cents,min_stock_qty) VALUES (?,?,?,?,?,?)');$pdo->prepare($insert)->execute([$tenantId,$unitId,$productId,0,$item['average_cost_cents']??0,$item['min_stock_qty']??0]);$inv=$pdo->prepare(Database::portableSql($pdo,'SELECT * FROM unit_inventory WHERE tenant_id=? AND unit_id=? AND product_id=? FOR UPDATE'));$inv->execute([$tenantId,$unitId,$productId]);$inventory=$inv->fetch();if(!$inventory)throw new RuntimeException('Saldo não encontrado para '.$item['name'].'.');$currentPhysical=(float)$inventory['stock_qty']+$reservedQty;$difference=round($counted-$currentPhysical,6);$newAvailable=round($counted-$reservedQty,6);$movementId=null;if(abs($difference)>.0005){$pdo->prepare('UPDATE unit_inventory SET stock_qty=?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND unit_id=? AND product_id=?')->execute([$newAvailable,$tenantId,$unitId,$productId]);$cost=(int)$inventory['average_cost_cents'];$key='inventory-count:'.$countId.':product:'.$productId;$exists=$pdo->prepare('SELECT id FROM stock_movements WHERE tenant_id=? AND idempotency_key=?');$exists->execute([$tenantId,$key]);$movementId=(int)$exists->fetchColumn();if($movementId<1){$m=$pdo->prepare('INSERT INTO stock_movements (tenant_id,unit_id,product_id,order_id,type,quantity,idempotency_key,unit_cost_cents,total_cost_cents,reason,performed_by) VALUES (?,?,?,NULL,"adjustment",?,?,?,?,?,?)');$m->execute([$tenantId,$unitId,$productId,$difference,$key,$cost,(int)round($cost*$difference),'Ajuste pela contagem física #'.$countId,$userId]);$movementId=(int)$pdo->lastInsertId();}$this->syncLegacyProduct($pdo,$tenantId,$productId);}$pdo->prepare('UPDATE inventory_count_items SET expected_qty=?,difference_qty=?,adjustment_movement_id=? WHERE id=?')->execute([round($currentPhysical,6),$difference,$movementId?:null,$item['id']]);}$pdo->prepare('UPDATE inventory_counts SET status="approved",approved_by=?,approved_at=CURRENT_TIMESTAMP,closed_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=? AND status="open"')->execute([$userId,$countId,$tenantId]);});Auth::audit('inventory.count_approved','inventory_count',(string)$countId,['unit_id'=>$unitId]);
    }

    public function cancel(int$countId,string$reason=''): void
    {
        Auth::requirePermission('inventory.manage');$tenantId=Auth::tenantId();if(!$tenantId)return;$current=(new OperatingUnitService())->requireCurrent();$unitId=(int)$current['id'];$reason=mb_substr(trim($reason),0,500);Database::transaction(function(PDO$pdo)use($tenantId,$unitId,$countId):void{$count=$this->lockedCount($pdo,$tenantId,$countId);if((int)$count['unit_id']!==$unitId)throw new RuntimeException('Esta contagem pertence a outra unidade.');if($count['status']==='cancelled')return;if($count['status']!=='open')throw new RuntimeException('Contagem aprovada não pode ser cancelada.');$pdo->prepare('UPDATE inventory_counts SET status="cancelled",closed_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=?')->execute([$countId,$tenantId]);});Auth::audit('inventory.count_cancelled','inventory_count',(string)$countId,['reason'=>$reason]);
    }

    public function list(int$limit=50): array
    {
        Auth::requirePermission('inventory.manage');$tenantId=Auth::tenantId();if(!$tenantId)return[];$unit=(new OperatingUnitService())->requireCurrent();$s=Database::connection()->prepare('SELECT ic.*,u.name created_by_name,au.name approved_by_name,(SELECT COUNT(*) FROM inventory_count_items i WHERE i.inventory_count_id=ic.id) items_total,(SELECT COUNT(*) FROM inventory_count_items i WHERE i.inventory_count_id=ic.id AND i.counted_qty IS NOT NULL) items_counted,(SELECT COUNT(*) FROM inventory_count_items i WHERE i.inventory_count_id=ic.id AND ABS(COALESCE(i.difference_qty,0))>.0005) differences FROM inventory_counts ic LEFT JOIN users u ON u.id=ic.created_by LEFT JOIN users au ON au.id=ic.approved_by WHERE ic.tenant_id=? AND ic.unit_id=? ORDER BY ic.id DESC LIMIT '.max(1,min(200,$limit)));$s->execute([$tenantId,$unit['id']]);return$s->fetchAll();
    }

    public function details(int$countId): array
    {
        Auth::requirePermission('inventory.manage');$tenantId=Auth::tenantId();if(!$tenantId)throw new RuntimeException('Empresa inválida.');$unit=(new OperatingUnitService())->requireCurrent();$pdo=Database::connection();$s=$pdo->prepare('SELECT ic.*,ou.name unit_name,u.name created_by_name,au.name approved_by_name FROM inventory_counts ic JOIN operating_units ou ON ou.id=ic.unit_id LEFT JOIN users u ON u.id=ic.created_by LEFT JOIN users au ON au.id=ic.approved_by WHERE ic.id=? AND ic.tenant_id=?');$s->execute([$countId,$tenantId]);$count=$s->fetch();if(!$count)throw new RuntimeException('Contagem não encontrada.');if((int)$count['unit_id']!==(int)$unit['id'])throw new RuntimeException('Esta contagem pertence a outra unidade.');$i=$pdo->prepare('SELECT ici.*,p.name product_name,p.sku,p.stock_unit,COALESCE((SELECT SUM(sr.quantity) FROM stock_reservations sr WHERE sr.tenant_id=? AND sr.unit_id=? AND sr.product_id=ici.product_id AND sr.status="reserved"),0) reserved_now FROM inventory_count_items ici JOIN products p ON p.id=ici.product_id WHERE ici.inventory_count_id=? ORDER BY p.name');$i->execute([$tenantId,$unit['id'],$countId]);return['count'=>$count,'items'=>$i->fetchAll()];
    }

    private function lockedCount(PDO$pdo,int$tenantId,int$countId): array{$s=$pdo->prepare(Database::portableSql($pdo,'SELECT * FROM inventory_counts WHERE id=? AND tenant_id=? FOR UPDATE'));$s->execute([$countId,$tenantId]);$count=$s->fetch();if(!$count)throw new RuntimeException('Contagem não encontrada.');return$count;}
    private function syncLegacyProduct(PDO$pdo,int$tenantId,int$productId): void{$s=$pdo->prepare('SELECT COALESCE(SUM(stock_qty),0) qty,CASE WHEN COALESCE(SUM(stock_qty),0)>0 THEN CAST(ROUND(SUM(stock_qty*average_cost_cents)/SUM(stock_qty)) AS INTEGER) ELSE MAX(average_cost_cents) END avg_cost FROM unit_inventory WHERE tenant_id=? AND product_id=?');$s->execute([$tenantId,$productId]);$row=$s->fetch()?:['qty'=>0,'avg_cost'=>0];$pdo->prepare('UPDATE products SET stock_qty=?,average_cost_cents=? WHERE id=? AND tenant_id=?')->execute([(float)$row['qty'],(int)($row['avg_cost']??0),$productId,$tenantId]);}
    private function formatQty(float$qty):string{if(abs($qty-round($qty))<.0005)return(string)(int)round($qty);return rtrim(rtrim(number_format($qty,3,',','.'),'0'),',');}
}
